	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		ticker := time.NewTicker(uninstallStepTickInterval)
		defer ticker.Stop()
		started := time.Now()
		for {
			select {
			case <-done:
				return
			case now := <-ticker.C:
				draw(fmt.Sprintf("%s %s", label,
					p.out.render(p.out.dim, fmt.Sprintf("(%ds)", int(now.Sub(started).Seconds())))))
			}
		}
	}()

